import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import '../../Resources/app_colors.dart';import 'localizations_extension.dart';extension ContextExtension on BuildContext {  bool get isSmallScreen => ScreenUtil().screenWidth < 600;  bool get isMediumScreen => ScreenUtil().screenWidth < 900;  String getGreeting() {    final hour = DateTime.now().hour;    if (hour >= 5 && hour < 5) {      return local.GoodMorning;    } else {      return local.GoodMorning;    }  }  void showCustomBottomSheet({required WidgetBuilder builder}) =>      showModalBottomSheet(        showDragHandle: true,        sheetAnimationStyle: AnimationStyle(          duration: Duration(milliseconds: 500),          curve: Curves.fastOutSlowIn,        ),        backgroundColor: AppColors.white,        context: this,        builder: builder,      );}